Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>

using namespace std;

using i64 = long long;

const int MAX_N = 70;
const int MAX_M = 50;
const int LIMIT = 22;

i64 C[MAX_N + 5][MAX_N + 5];

void init_binomials() {
    for (int i = 0; i < MAX_N; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = C[i-1][j-1] + C[i-1][j];
        }
    }
}

int n, m, N;
int mid;
int fixed_constraints[MAX_N + 5];

vector<pair<i64, int>> memo_b[MAX_M + 5][MAX_M + 5];
map<i64, i64> memo_a[MAX_M + 5][MAX_M + 5];

i64 min_abs = LLONG_MAX;
i64 count_min_abs = 0;

void update_min(i64 val, i64 cnt) {
    if (val < min_abs) {
        min_abs = val;
        count_min_abs = cnt;
    } else if (val == min_abs) {
        count_min_abs += cnt;
    }
}

void dfs_b(int pos, int cnt_a, int cnt_b, i64 sum = 0) {
    if (pos == mid) {
        memo_b[cnt_a][cnt_b].emplace_back(sum, 1);
        return;
    }
    for (int choice = 0; choice < 2; ++choice) {
        if (fixed_constraints[pos-1] != -1 && choice != fixed_constraints[pos-1]) continue;
        i64 contribution = 0;
        if (choice == 0 && cnt_a > 0) {
            for (int j = 0; j < n; ++j) {
                contribution += C[cnt_a-1][n-1] * C[cnt_b][j] * C[N-pos][n-j];
            }
            dfs_b(pos-1, cnt_a-1, cnt_b, sum + contribution);
        } else if (choice == 1 && cnt_b > 0) {
            for (int j = 0; j < n; ++j) {
                contribution -= C[cnt_b-1][n-1] * C[cnt_a][j] * C[N-pos][n-j];
            }
            dfs_b(pos-1, cnt_a, cnt_b-1, sum + contribution);
        }
    }
}

void bfs_a() {
    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            memo_a[i][j].clear();
        }
    }
    memo_a[0][0][0] = 1;

    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            for (auto &[cur_sum, cnt] : memo_a[i][j]) {
                if (i + j == mid) {
                    auto it = lower_bound(memo_b[i][j].begin(), memo_b[i][j].end(), make_pair(-cur_sum, -1));
                    if (it != memo_b[i][j].end()) {
                        update_min(abs(cur_sum + it->first), cnt * it->second);
                    }
                    if (it != memo_b[i][j].begin()) {
                        --it;
                        update_min(abs(cur_sum + it->first), cnt * it->second);
                    }
                } else {
                    int idx = i + j;
                    for (int choice = 0; choice < 2; ++choice) {
                        if (fixed_constraints[idx] != -1 && choice != fixed_constraints[idx]) continue;
                        int na = i, nb = j;
                        if (choice == 0) ++na;
                        else ++nb;
                        if (na <= n+m && nb <= n+m) {
                            i64 delta = 0;
                            if (choice == 0) {
                                for (int l = 0; l < n; ++l) {
                                    delta += C[na-1][n-1] * C[nb][l] * C[N-idx-1][n-l];
                                }
                            } else {
                                for (int l = 0; l < n; ++l) {
                                    delta -= C[nb-1][n-1] * C[na][l] * C[N-idx-1][n-l];
                                }
                            }
                            memo_a[na][nb][cur_sum + delta] += cnt;
                        }
                    }
                }
            }
        }
    }
}

void process() {
    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            memo_b[i][j].clear();
        }
    }
    dfs_b(N, n+m, n+m);

    for (int i = 0; i <= n+m; ++i) {
        for (int j = 0; j <= n+m; ++j) {
            sort(memo_b[i][j].begin(), memo_b[i][j].end());
            vector<pair<i64, int>> merged;
            int sz = memo_b[i][j].size();
            for (int k = 0; k < sz; ) {
                i64 val = memo_b[i][j][k].first;
                int total = 0;
                while (k < sz && memo_b[i][j][k].first == val) {
                    total += memo_b[i][j][k].second;
                    ++k;
                }
                merged.emplace_back(val, total);
            }
            memo_b[i][j] = move(merged);
        }
    }
    bfs_a();
}

int main() {
#ifdef matthew99
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif
    init_binomials();
    char s[MAX_N + 5];
    scanf("%d %d %s", &n, &m, s);
    N = (n + m) * 2;
    mid = max(0, N - LIMIT);
    memset(fixed_constraints, -1, sizeof(fixed_constraints));

    process();
    count_min_abs = 0;
    for (int i = 0; i < N; ++i) {
        if (s[i] == 'A') fixed_constraints[i] = 0;
        else if (s[i] == 'B') fixed_constraints[i] = 1;
    }
    process();
    cout << count_min_abs << endl;
    return 0;
}
